let token = TokenClient::new(&env, &token_addr);          // SEP-41: balance, transfer,
token.transfer(&from, &to, &amount);                      // approve, transfer_from, burn…

let sac = StellarAssetClient::new(&env, &sac_addr);       // SAC admin surface:
sac.mint(&to, &amount);                   
